cd "C:/visual projects/reverse-kit/pipeline/_work/run_wol2/records"; python - <<'E'
import yaml,glob,re,os
out=[];tot=0
def walk(o,path,f):
    global tot
    if isinstance(o,dict):
        for k,v in o.items():
            if k in('open_questions','questions','open_issues') and isinstance(v,list):
                for q in v:
                    tot+=1
                    out.append((os.path.basename(f),str(q)))
            else: walk(v,path,f)
    elif isinstance(o,list):
        for x in o: walk(x,path,f)
for f in sorted(glob.glob('*/*.yaml')):
    try: d=yaml.safe_load(open(f,encoding='utf8'))
    except Exception as e: print('ERR',f,e); continue
    walk(d,'',f)
print(tot)
import json
json.dump(out,open(os.environ['TEMP']+'/oqs.json','w',encoding='utf8'),ensure_ascii=False)
pat=re.compile(r"спек|расхожд|а не |по коду|опечат|ошибк|противореч|отлич|вместо",re.I)
sel=[(f,q) for f,q in out if pat.search(q)]
print(len(sel))
open(os.environ['TEMP']+'/oqsel.txt','w',encoding='utf8').write("\n".join(f"{f}: {q[:450]}" for f,q in sel))
E

