	private bool prescriptionWritten;

	public override void Start()
	{
		CompassIndicatorTrigger.Spawn(Compass.CompassIndicatorType.NurseRoom, transform.position, transform);
	}

	public override bool HandleConditionalInteraction()
	{
		switch (DialogManager.dialogDict[myDialogID].CurrentIndex)
		{
		case 0:
			if (prescriptionWritten)
			{
				DialogManager.dialogDict[myDialogID].CurrentIndex = 5;
			}
			SoundManager.PlayAudio("Doctor" + Random.Range(0, 3), Random.Range(0.85f, 0.95f));
			PoolManager.GetPoolItem<EmoteEmitter>().Emit(EmoteType.Hmm, 1, transform.position + Vector3.up * 3f);
			break;
		case 1:
			if (!prescriptionWritten && player != null && player.inventory.ContainsItem("TokenDoctor"))
			{
				DialogManager.dialogDict[myDialogID].CurrentIndex = 2;
			}
			break;
		case 2:
			if (!prescriptionWritten)
			{
				if (player != null && player.GetRandomStandardSkill() != null)
				{
					WritePrescription();
				}
				else
				{
					DialogManager.dialogDict[myDialogID].CurrentIndex = 3;
				}
			}
			break;
		case 3:
			if (!prescriptionWritten && player != null)
			{
				WritePrescription(useToken: true);
			}
			break;
		case 4:
			if (!prescriptionWritten)
			{
				playerLeavingDialog = true;
				return true;
			}
			break;
		case 5:
			if (prescriptionWritten)
			{
				playerLeavingDialog = true;
				return true;
			}
			break;
		}
		return false;
	}

	private void WritePrescription(bool useToken = false)
	{
		prescriptionWritten = true;
		DialogManager.dialogDict[myDialogID].CurrentIndex = 4;
		if (useToken)
		{
			player.inventory.RemoveItem("TokenDoctor", forceOverride: false, showNotice: true);
			LootManager.DropHealth(transform.position, healthDropCount + 2);
		}
		else
		{
			player.RemoveSkill(player.GetRandomStandardSkill(allowEmp: false) ?? player.GetRandomStandardSkill());
			LootManager.DropHealth(transform.position, healthDropCount);
		}
		RunData.miscNurseRoomFound = true;
